<?php
namespace App\controllers;
use App\config\Database;
use App\repositories\UserRepository;
use App\services\CreditService;
use App\services\FinancialService;
use App\utils\Audit;
use App\utils\Cache;
use App\utils\Request;
use App\utils\Response;
final class AdminController {
    public function dashboard():array{$pdo=Database::get();$m=[];$m['users']=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$m['companies']=(int)$pdo->query('SELECT COUNT(*) FROM companies')->fetchColumn();$m['subscriptions']=(int)$pdo->query("SELECT COUNT(*) FROM subscriptions WHERE status='active'")->fetchColumn();$m['credits_used']=(int)$pdo->query("SELECT COALESCE(SUM(credits_used),0) FROM agent_runs WHERE status='success' AND created_at>=DATE_FORMAT(NOW(),'%Y-%m-01')")->fetchColumn();$m['runs']=(int)$pdo->query("SELECT COUNT(*) FROM agent_runs WHERE status='success' AND created_at>=DATE_FORMAT(NOW(),'%Y-%m-01')")->fetchColumn();$m['tokens']=(int)$pdo->query("SELECT COALESCE(SUM(input_tokens+output_tokens),0) FROM agent_runs WHERE created_at>=DATE_FORMAT(NOW(),'%Y-%m-01')")->fetchColumn();$m['finance']=(new FinancialService())->summary($_GET['month']??null);return ['metrics'=>$m];}
    public function users():array{$page=Request::queryInt('page',1,1,100000);$per=Request::queryInt('per_page',30,5,100);$search=mb_substr(trim((string)($_GET['search']??'')),0,100);$r=(new UserRepository())->list($page,$per,$search);return ['users'=>$r['items'],'pagination'=>['page'=>$page,'per_page'=>$per,'total'=>$r['total'],'pages'=>(int)ceil($r['total']/$per)]];}
    public function updateUser(array $admin,int $id):array{$d=Request::json();$pdo=Database::get();$s=$pdo->prepare('SELECT id,role,status FROM users WHERE id=?');$s->execute([$id]);$before=$s->fetch();if(!$before)Response::json(['error'=>'Usuário não encontrado.'],404);if($id===(int)$admin['id']&&isset($d['status'])&&$d['status']!=='active')throw new \RuntimeException('Você não pode bloquear a própria conta.');$set=[];$vals=[];if(isset($d['status'])&&in_array($d['status'],['active','blocked'],true)){$set[]='status=?';$vals[]=$d['status'];}if(isset($d['role'])&&in_array($d['role'],['user','admin'],true)){$set[]='role=?';$vals[]=$d['role'];}if($set){$vals[]=$id;$pdo->prepare('UPDATE users SET '.implode(',',$set).',updated_at=NOW() WHERE id=?')->execute($vals);}if(isset($d['plan_id'])){$pid=(int)$d['plan_id'];$p=$pdo->prepare('SELECT id,duration_days FROM plans WHERE id=?');$p->execute([$pid]);$plan=$p->fetch();if(!$plan)throw new \RuntimeException('Plano inválido.');$pdo->prepare("INSERT INTO subscriptions(user_id,plan_id,provider,status,starts_at,current_period_start,current_period_end,created_at,updated_at) VALUES(?,?,'internal','active',NOW(),NOW(),DATE_ADD(NOW(),INTERVAL ? DAY),NOW(),NOW()) ON DUPLICATE KEY UPDATE plan_id=VALUES(plan_id),provider='internal',status='active',current_period_start=NOW(),current_period_end=VALUES(current_period_end),updated_at=NOW()")->execute([$id,$pid,$plan['duration_days']]);}Audit::record((int)$admin['id'],'update','user',$id,$before,$d);return ['message'=>'Usuário atualizado.'];}
    public function adjustCredits(array $admin,int $id):array{$d=Request::json();$amount=(int)($d['amount']??0);if($amount===0)throw new \RuntimeException('Informe uma quantidade diferente de zero.');$pdo=Database::get();if($amount>0){(new CreditService())->grant($id,$amount,'Ajuste manual do administrador','admin_adjustment',(string)$admin['id']);}else{$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT balance FROM user_credits WHERE user_id=? FOR UPDATE');$s->execute([$id]);$bal=(int)$s->fetchColumn();$new=max(0,$bal+$amount);$removed=$bal-$new;$pdo->prepare('UPDATE user_credits SET balance=?,updated_at=NOW() WHERE user_id=?')->execute([$new,$id]);$pdo->prepare("INSERT INTO credit_transactions(user_id,type,amount,balance_after,description,reference_type,reference_id,status,created_at) VALUES(?,'adjustment',?,?,'Ajuste manual do administrador','admin_adjustment',?,'confirmed',NOW())")->execute([$id,$removed,$new,(string)$admin['id']]);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}Audit::record((int)$admin['id'],'adjust_credits','user',$id,null,['amount'=>$amount]);return ['message'=>'Créditos ajustados.'];}
    public function deleteUser(array $admin,int $id):array{if($id===(int)$admin['id'])throw new \RuntimeException('Você não pode excluir a própria conta por esta tela.');$pdo=Database::get();$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$before=$s->fetch();if(!$before)Response::json(['error'=>'Usuário não encontrado.'],404);$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);Audit::record((int)$admin['id'],'delete','user',$id,$before,null);return ['message'=>'Usuário excluído.'];}
    public function agents():array{$rows=Database::get()->query('SELECT a.*,p.name provider,m.model_name,m.display_name model_display FROM agents a JOIN ai_providers p ON p.id=a.provider_id JOIN ai_models m ON m.id=a.model_id ORDER BY a.sort_order,a.id')->fetchAll();foreach($rows as &$r)$r['input_schema']=json_decode((string)$r['input_schema'],true)?:[];return ['agents'=>$rows];}
    public function createAgent(array $admin):never{$d=Request::json();$schema=$d['input_schema']??[];if(!is_array($schema))throw new \RuntimeException('Schema inválido.');$pdo=Database::get();$pdo->prepare('INSERT INTO agents(name,slug,description,icon,category,system_prompt,input_schema,provider_id,model_id,temperature,max_tokens,credit_cost,active,sort_order,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())')->execute([mb_substr((string)($d['name']??'Novo agente'),0,120),mb_substr((string)($d['slug']??('agente-'.time())),0,80),mb_substr((string)($d['description']??''),0,500),mb_substr((string)($d['icon']??'zap'),0,80),mb_substr((string)($d['category']??'Geral'),0,80),(string)($d['system_prompt']??'Você é um assistente empresarial.'),json_encode($schema,JSON_UNESCAPED_UNICODE),(int)($d['provider_id']??1),(int)($d['model_id']??1),(float)($d['temperature']??.4),(int)($d['max_tokens']??1200),max(1,(int)($d['credit_cost']??1)),(int)!empty($d['active']), (int)($d['sort_order']??99)]);$id=(int)$pdo->lastInsertId();Cache::clear();Audit::record((int)$admin['id'],'create','agent',$id,null,$d);Response::json(['id'=>$id],201);}
    public function updateAgent(array $admin,int $id):array{$d=Request::json();$pdo=Database::get();$s=$pdo->prepare('SELECT * FROM agents WHERE id=?');$s->execute([$id]);$before=$s->fetch();if(!$before)Response::json(['error'=>'Agente não encontrado.'],404);$allowed=['name','slug','description','icon','category','system_prompt','provider_id','model_id','temperature','max_tokens','credit_cost','active','sort_order'];$set=[];$vals=[];foreach($allowed as $k)if(array_key_exists($k,$d)){$set[]="$k=?";$vals[]=$d[$k];}if(array_key_exists('input_schema',$d)){$set[]='input_schema=?';$vals[]=json_encode($d['input_schema'],JSON_UNESCAPED_UNICODE);}if($set){$vals[]=$id;$pdo->prepare('UPDATE agents SET '.implode(',',$set).',updated_at=NOW() WHERE id=?')->execute($vals);}Cache::clear();Audit::record((int)$admin['id'],'update','agent',$id,$before,$d);return ['message'=>'Agente atualizado.'];}
    public function deleteAgent(array $admin,int $id):array{Database::get()->prepare('UPDATE agents SET active=0,updated_at=NOW() WHERE id=?')->execute([$id]);Cache::clear();Audit::record((int)$admin['id'],'disable','agent',$id);return ['message'=>'Agente desativado.'];}
    public function providers():array{$pdo=Database::get();return ['providers'=>$pdo->query('SELECT * FROM ai_providers ORDER BY id')->fetchAll(),'models'=>$pdo->query('SELECT m.*,p.name provider_name FROM ai_models m JOIN ai_providers p ON p.id=m.provider_id ORDER BY m.provider_id,m.id')->fetchAll()];}
    public function updateProvider(array $admin,int $id):array{$d=Request::json();Database::get()->prepare('UPDATE ai_providers SET active=?,updated_at=NOW() WHERE id=?')->execute([(int)!empty($d['active']),$id]);Audit::record((int)$admin['id'],'update','provider',$id,null,$d);return ['message'=>'Provider atualizado.'];}
    public function createModel(array $admin):never{$d=Request::json();$pdo=Database::get();$pdo->prepare('INSERT INTO ai_models(provider_id,model_name,display_name,active,input_cost_per_million,output_cost_per_million,cost_currency,created_at,updated_at) VALUES(?,?,?,?,?,?,?,NOW(),NOW())')->execute([(int)$d['provider_id'],mb_substr((string)$d['model_name'],0,120),mb_substr((string)($d['display_name']??$d['model_name']),0,120),(int)!empty($d['active']),($d['input_cost_per_million']??'')===''?null:(float)$d['input_cost_per_million'],($d['output_cost_per_million']??'')===''?null:(float)$d['output_cost_per_million'],in_array(($d['cost_currency']??'USD'),['USD','BRL'],true)?$d['cost_currency']:'USD']);$id=(int)$pdo->lastInsertId();Audit::record((int)$admin['id'],'create','ai_model',$id,null,$d);Response::json(['id'=>$id],201);}
    public function updateModel(array $admin,int $id):array{$d=Request::json();$allowed=['model_name','display_name','active','input_cost_per_million','output_cost_per_million','cost_currency'];$set=[];$vals=[];foreach($allowed as $k)if(array_key_exists($k,$d)){$set[]="$k=?";$vals[]=$d[$k]===''?null:$d[$k];}if($set){$vals[]=$id;Database::get()->prepare('UPDATE ai_models SET '.implode(',',$set).',updated_at=NOW() WHERE id=?')->execute($vals);}Audit::record((int)$admin['id'],'update','ai_model',$id,null,$d);return ['message'=>'Modelo atualizado.'];}
    public function plans():array{$rows=Database::get()->query('SELECT * FROM plans ORDER BY sort_order,price')->fetchAll();foreach($rows as &$r){$r['features']=json_decode((string)$r['features'],true)?:[];$r['limits']=json_decode((string)$r['limits_json'],true)?:[];}return ['plans'=>$rows];}
    public function createPlan(array $admin):never{$d=Request::json();$pdo=Database::get();$pdo->prepare('INSERT INTO plans(name,slug,description,price,credits,duration_days,billing_frequency,billing_frequency_type,features,limits_json,active,sort_order,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())')->execute([mb_substr((string)$d['name'],0,100),mb_substr((string)$d['slug'],0,100),mb_substr((string)($d['description']??''),0,255),(float)($d['price']??0),(int)($d['credits']??0),(int)($d['duration_days']??30),(int)($d['billing_frequency']??1),in_array(($d['billing_frequency_type']??'months'),['days','months'],true)?$d['billing_frequency_type']:'months',json_encode($d['features']??[],JSON_UNESCAPED_UNICODE),json_encode($d['limits']??[],JSON_UNESCAPED_UNICODE),(int)!empty($d['active']),(int)($d['sort_order']??99)]);$id=(int)$pdo->lastInsertId();Cache::clear();Audit::record((int)$admin['id'],'create','plan',$id,null,$d);Response::json(['id'=>$id],201);}
    public function updatePlan(array $admin,int $id):array{$d=Request::json();$allowed=['name','slug','description','price','credits','duration_days','billing_frequency','billing_frequency_type','mercado_pago_plan_id','active','sort_order'];$set=[];$vals=[];foreach($allowed as $k)if(array_key_exists($k,$d)){$set[]="$k=?";$vals[]=$d[$k];}if(isset($d['features'])){$set[]='features=?';$vals[]=json_encode($d['features'],JSON_UNESCAPED_UNICODE);}if(isset($d['limits'])){$set[]='limits_json=?';$vals[]=json_encode($d['limits'],JSON_UNESCAPED_UNICODE);}if($set){$vals[]=$id;Database::get()->prepare('UPDATE plans SET '.implode(',',$set).',updated_at=NOW() WHERE id=?')->execute($vals);}Cache::clear();Audit::record((int)$admin['id'],'update','plan',$id,null,$d);return ['message'=>'Plano atualizado.'];}
    public function finance():array{return ['finance'=>(new FinancialService())->summary($_GET['month']??null),'costs'=>$this->costRows(),'payments'=>$this->paymentRows()];}
    private function costRows():array{return Database::get()->query('SELECT * FROM system_costs ORDER BY reference_month DESC,id DESC LIMIT 100')->fetchAll();}
    private function paymentRows():array{return Database::get()->query('SELECT pay.id,pay.status,pay.amount,pay.paid_at,pay.provider_payment_id,u.name user_name,u.email,p.name plan_name FROM payments pay JOIN users u ON u.id=pay.user_id JOIN plans p ON p.id=pay.plan_id ORDER BY pay.id DESC LIMIT 100')->fetchAll();}
    public function addCost(array $admin):never{$d=Request::json();$cat=in_array(($d['category']??''),['infrastructure','other'],true)?$d['category']:'other';$month=preg_match('/^\d{4}-\d{2}$/',(string)($d['month']??''))?$d['month'].'-01':date('Y-m-01');$pdo=Database::get();$pdo->prepare('INSERT INTO system_costs(category,description,amount_brl,reference_month,recurring,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())')->execute([$cat,mb_substr((string)($d['description']??'Custo'),0,190),(float)($d['amount_brl']??0),$month,(int)!empty($d['recurring'])]);$id=(int)$pdo->lastInsertId();Audit::record((int)$admin['id'],'create','system_cost',$id,null,$d);Response::json(['id'=>$id],201);}
    public function deleteCost(array $admin,int $id):array{Database::get()->prepare('DELETE FROM system_costs WHERE id=?')->execute([$id]);Audit::record((int)$admin['id'],'delete','system_cost',$id);return ['message'=>'Custo excluído.'];}
    public function logs():array{$pdo=Database::get();return ['security'=>$pdo->query('SELECT * FROM security_logs ORDER BY id DESC LIMIT 100')->fetchAll(),'audit'=>$pdo->query('SELECT a.*,u.name actor_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id ORDER BY a.id DESC LIMIT 100')->fetchAll(),'webhooks'=>$pdo->query('SELECT * FROM webhook_events ORDER BY id DESC LIMIT 100')->fetchAll()];}
}
